const $=id=>document.getElementById(id);
const KEY='chroma-daily-progress-v1';
const MS_DAY=86400000;
let current=null,dayKey='',selected=-1,progress={answers:{},best:0};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved.answers==='object')progress=saved}catch{}
function todayUTC(){return new Date().toISOString().slice(0,10)}
function dayIndex(date,launch){return Math.floor((Date.parse(date+'T00:00:00Z')-Date.parse(launch+'T00:00:00Z'))/MS_DAY)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(progress))}catch{}}
function statistics(){const dates=Object.keys(progress.answers).filter(d=>progress.answers[d]?.finished).sort();const wins=dates.filter(d=>progress.answers[d].correct).length;let streak=0;let d=todayUTC();if(!progress.answers[d]?.correct)d=new Date(Date.parse(d+'T00:00:00Z')-MS_DAY).toISOString().slice(0,10);while(progress.answers[d]?.correct){streak++;d=new Date(Date.parse(d+'T00:00:00Z')-MS_DAY).toISOString().slice(0,10)}return {played:dates.length,winRate:dates.length?Math.round(100*wins/dates.length):0,streak,best:Math.max(progress.best||0,streak)}}
function countdown(){const now=Date.now(),next=Math.ceil(now/MS_DAY)*MS_DAY,seconds=Math.max(0,Math.floor((next-now)/1000));$('countdown').textContent=[Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(n=>String(n).padStart(2,'0')).join(':');if(todayUTC()!==dayKey)location.reload()}
function reveal(correct){$('question-area').hidden=true;$('result-area').hidden=false;$('outcome-kicker').textContent=correct?'✦ CORRECT ANSWER':'✦ THE REVEAL';$('outcome-title').textContent=correct?'You read the colors!':'Not quite — now you see it.';$('outcome-description').textContent=`Today's film was ${current.title}.`;$('film-title').textContent=current.title;$('film-description').textContent=`${current.year} · ${current.genre} · ${current.license}`;$('license-link').href=current.source;$('filmstrip').innerHTML=Array.from({length:5},(_,i)=>`<figure><img src="assets/${current.id}-${i+1}.jpg" alt="Frame ${i+1} from ${current.title}" loading="lazy"><figcaption>FRAME ${i+1}</figcaption></figure>`).join('');$('streak-count').textContent=statistics().streak;countdown()}
function draw(){selected=-1;$('barcode').src=`assets/${current.id}-barcode.png`;$('choices').innerHTML='';current.choices.forEach((movie,i)=>{const button=document.createElement('button');button.className='choice';button.innerHTML=`<span class="letter">${'ABCD'[i]}</span><div><span class="title"></span><span class="year"></span></div>`;button.querySelector('.title').textContent=movie.title;button.querySelector('.year').textContent=movie.year;button.onclick=()=>{selected=i;document.querySelectorAll('.choice').forEach((b,j)=>b.classList.toggle('selected',j===i));$('submit').disabled=false;$('guess-label').textContent='READY TO REVEAL'};$('choices').appendChild(button)});$('submit').onclick=()=>{if(selected<0)return;const correct=selected===current.answer;progress.answers[dayKey]={finished:true,correct,puzzle:current.id,guess:selected};progress.best=Math.max(progress.best||0,statistics().streak);save();reveal(correct)};if(progress.answers[dayKey]?.finished)reveal(progress.answers[dayKey].correct)}
async function init(){let data;try{const response=await fetch('puzzles.json',{cache:'no-store'});if(!response.ok)throw Error('Catalog unavailable');data=await response.json()}catch{$('availability-note').textContent='The daily catalog could not be loaded. Please refresh.';return}dayKey=todayUTC();let i=dayIndex(dayKey,data.launch_date);if(i<0)i=0;if(!data.puzzles.length){$('availability-note').textContent='No movies are ready yet.';return}if(i>=data.puzzles.length){$('availability-note').textContent='Pilot catalog exhausted. More licensed films must be added before new daily challenges can continue.';$('question-area').hidden=true;$('barcode').style.display='none';return}current=data.puzzles[i];$('puzzle-number').textContent=`#${String(i+1).padStart(3,'0')}`;$('round-label').textContent=`FILM #${String(i+1).padStart(3,'0')} · TODAY'S COLORS`;$('availability-note').textContent='One shared puzzle worldwide · Resets at 00:00 UTC';draw()}
$('stats-open').onclick=()=>{const s=statistics();$('stat-played').textContent=s.played;$('stat-won').textContent=s.winRate+'%';$('stat-current').textContent=s.streak;$('stat-best').textContent=s.best;$('stats-dialog').showModal()};$('stats-close').onclick=()=>$('stats-dialog').close();$('stats-dialog').addEventListener('click',e=>{if(e.target===$('stats-dialog'))$('stats-dialog').close()});
init();setInterval(()=>{if(current&&$('result-area').hidden===false)countdown();else if(todayUTC()!==dayKey)location.reload()},1000);
